// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import org.junit.jupiter.api.Test;

/**
 * Unit spec for the bounded local reorder for factorization: within one {@link MultiJoinPlan} join group, orders
 * reachable by at most three moves — each move shifts one statement pattern one position up or down (an adjacent
 * transposition) — may replace the selected factorized order, but only on a strictly larger claimed tail and only when
 * the guards hold: swaps exchange adjacent {@link PatternPlan}s exclusively, a depth-0 swap requires the incoming
 * pattern's static estimate within a factor-2 band of the displaced root's, no candidate may introduce a cartesian step
 * (connectivity counts slots bound outside the group — the seed mask), and a pattern may not leave the flat prefix when
 * it is more selective than every pattern remaining there (the sink's pruning-floor rule).
 */
public class LmdbNativeFactorizedReorderTest {

	private static final int S = 0;
	private static final int X = 1;
	private static final int A = 2;
	private static final int B = 3;
	private static final int C = 4;
	private static final int G = 5;
	private static final int Q = 6;
	private static final int T = 7;

	private static PatternPlan pattern(Term s, long p, Term o, double estimate) {
		return new PatternPlan(s, Term.constant(p), o, Term.unbound(), ContextConstraint.UNRESTRICTED, false, estimate);
	}

	// --- rows side -------------------------------------------------------------------------------------------

	/**
	 * Compiler order [driver, binder, check, rblock]: every produced slot is shared, so the sink has no candidate, and
	 * the repeated-slot pattern at the end blocks the whole peel. One move (check down / rblock up) exposes check —
	 * whose slots are all bound by then — as a counting branch.
	 */
	@Test
	public void rowsBlockerSwapUnlocksTail() {
		PatternPlan driver = pattern(Term.slot(S), 11, Term.constant(21), 10);
		PatternPlan binder = pattern(Term.slot(S), 7, Term.slot(X), 100);
		PatternPlan check = pattern(Term.slot(S), 13, Term.slot(X), 500);
		PatternPlan rblock = pattern(Term.slot(S), 17, Term.slot(S), 50);
		MultiJoinPlan plan = new MultiJoinPlan(new SlotPlan[] { driver, binder, check, rblock }, new MaskedFilter[0]);

		// precondition: the sink is inert here (no exclusively produced slot anywhere)
		assertThat(plan.derivedFactorizedPlan(0L).order).containsExactly(driver, binder, check, rblock);

		MultiJoinPlan.OrderedPlan selected = LmdbNativeFactorizedRows.selectFactorizedOrder(plan, 0L, 0L, 0);

		assertThat(selected.order)
				.as("one down-move of the dead check past the repeated-slot blocker must unlock the tail")
				.containsExactly(driver, binder, rblock, check);
	}

	/** The same shape stays untouched when the kill switch is off. */
	@Test
	public void disabledFlagKeepsIncumbent() {
		PatternPlan driver = pattern(Term.slot(S), 11, Term.constant(21), 10);
		PatternPlan binder = pattern(Term.slot(S), 7, Term.slot(X), 100);
		PatternPlan check = pattern(Term.slot(S), 13, Term.slot(X), 500);
		PatternPlan rblock = pattern(Term.slot(S), 17, Term.slot(S), 50);
		MultiJoinPlan plan = new MultiJoinPlan(new SlotPlan[] { driver, binder, check, rblock }, new MaskedFilter[0]);

		System.setProperty("rdf4j.lmdb.factorizedReorder.enabled", "false");
		try {
			MultiJoinPlan.OrderedPlan selected = LmdbNativeFactorizedRows.selectFactorizedOrder(plan, 0L, 0L, 0);
			assertThat(selected.order).containsExactly(driver, binder, check, rblock);
		} finally {
			System.clearProperty("rdf4j.lmdb.factorizedReorder.enabled");
		}
	}

	/** An ORDER BY-style required prefix disables the layer entirely: prefix depths must not be permuted. */
	@Test
	public void requiredPrefixMaskDisablesReorder() {
		PatternPlan driver = pattern(Term.slot(S), 11, Term.constant(21), 10);
		PatternPlan binder = pattern(Term.slot(S), 7, Term.slot(X), 100);
		PatternPlan check = pattern(Term.slot(S), 13, Term.slot(X), 500);
		PatternPlan rblock = pattern(Term.slot(S), 17, Term.slot(S), 50);
		MultiJoinPlan plan = new MultiJoinPlan(new SlotPlan[] { driver, binder, check, rblock }, new MaskedFilter[0]);

		MultiJoinPlan.OrderedPlan selected = LmdbNativeFactorizedRows.selectFactorizedOrder(plan, 0L, 1L << S, 0);

		assertThat(selected.order).containsExactly(driver, binder, check, rblock);
	}

	/**
	 * A non-pattern child is an immovable wall: no swap may touch or cross it, so a join ending in a nested sub-plan
	 * keeps its incumbent order even though patterns before the wall would peel elsewhere.
	 */
	@Test
	public void nonPatternChildIsAWall() {
		PatternPlan driver = pattern(Term.slot(S), 11, Term.constant(21), 10);
		PatternPlan binder = pattern(Term.slot(S), 7, Term.slot(X), 100);
		PatternPlan check = pattern(Term.slot(S), 13, Term.slot(X), 500);
		MultiJoinPlan wall = new MultiJoinPlan(
				new SlotPlan[] { pattern(Term.slot(S), 19, Term.constant(31), 42) }, new MaskedFilter[0]);
		MultiJoinPlan plan = new MultiJoinPlan(new SlotPlan[] { driver, binder, check, wall }, new MaskedFilter[0]);

		MultiJoinPlan.OrderedPlan selected = LmdbNativeFactorizedRows.selectFactorizedOrder(plan, 0L, 0L, 0);

		assertThat(selected.order).containsExactly(driver, binder, check, wall);
	}

	// --- root swaps ------------------------------------------------------------------------------------------

	/**
	 * Compiler order [x, rblock, y1, y2]: the repeated-slot pattern caps the peel at two flat depths, and the sink
	 * cannot help (y1/y2 fall below its pruning floor). Rooting the repeated-slot pattern — the one place it blocks
	 * nothing — needs a depth-0 swap, allowed here because 20 vs 12 is within the factor-2 band; x itself then peels.
	 */
	@Test
	public void rootSwapWithinBandAdoptsBlockerAsRoot() {
		PatternPlan x = pattern(Term.slot(S), 7, Term.constant(23), 20);
		PatternPlan rblock = pattern(Term.slot(S), 17, Term.slot(S), 12);
		PatternPlan y1 = pattern(Term.slot(S), 19, Term.slot(B), 5);
		PatternPlan y2 = pattern(Term.slot(S), 23, Term.slot(C), 8);
		MultiJoinPlan plan = new MultiJoinPlan(new SlotPlan[] { x, rblock, y1, y2 }, new MaskedFilter[0]);

		// precondition: the sink's pruning floor (12) vetoes y1 (5) and y2 (8); nothing sinks
		assertThat(plan.derivedFactorizedPlan(0L).order).containsExactly(x, rblock, y1, y2);

		MultiJoinPlan.OrderedPlan selected = LmdbNativeFactorizedRows.selectFactorizedOrder(plan, 0L, 0L, 0);

		assertThat(selected.order)
				.as("a within-band root swap parks the repeated-slot blocker at depth 0")
				.containsExactly(rblock, x, y1, y2);
	}

	/** The same shape with the root estimate outside the 2x band keeps the incumbent order. */
	@Test
	public void rootSwapOutsideBandIsVetoed() {
		PatternPlan x = pattern(Term.slot(S), 7, Term.constant(23), 30);
		PatternPlan rblock = pattern(Term.slot(S), 17, Term.slot(S), 12);
		PatternPlan y1 = pattern(Term.slot(S), 19, Term.slot(B), 5);
		PatternPlan y2 = pattern(Term.slot(S), 23, Term.slot(C), 8);
		MultiJoinPlan plan = new MultiJoinPlan(new SlotPlan[] { x, rblock, y1, y2 }, new MaskedFilter[0]);

		MultiJoinPlan.OrderedPlan selected = LmdbNativeFactorizedRows.selectFactorizedOrder(plan, 0L, 0L, 0);

		assertThat(selected.order)
				.as("30 vs 12 exceeds the 2x band: the root must not change")
				.containsExactly(x, rblock, y1, y2);
	}

	/** An externally partitioned morsel root (minimumFlatCount == 1) may never be swapped away. */
	@Test
	public void externalRootMinimumBlocksRootSwap() {
		PatternPlan x = pattern(Term.slot(S), 7, Term.constant(23), 20);
		PatternPlan rblock = pattern(Term.slot(S), 17, Term.slot(S), 12);
		PatternPlan y1 = pattern(Term.slot(S), 19, Term.slot(B), 5);
		PatternPlan y2 = pattern(Term.slot(S), 23, Term.slot(C), 8);
		MultiJoinPlan plan = new MultiJoinPlan(new SlotPlan[] { x, rblock, y1, y2 }, new MaskedFilter[0]);

		MultiJoinPlan.OrderedPlan selected = LmdbNativeFactorizedRows.selectFactorizedOrder(plan, 0L, 0L, 1);

		assertThat(selected.order).containsExactly(x, rblock, y1, y2);
	}

	/**
	 * Chained root swaps must respect the 2x band against the <em>original</em> root, not just the previous one:
	 * estimates 40 → 21 → 11 admit each hop individually (pairwise within 2x) yet land 40/11 ≈ 3.6x away from the
	 * incumbent root. The drift order [vProducer, xCheck, x, vCheck] frees three branches and is reachable only through
	 * the chained swaps, so without a final-state band check it wins; with the band enforced against the incumbent root
	 * the only adoptable improvement is the root-preserving one-move order [x, vProducer, xCheck, vCheck].
	 */
	@Test
	public void chainedRootSwapsStayWithinBandOfOriginalRoot() {
		PatternPlan x = pattern(Term.slot(S), 7, Term.constant(101), 40);
		PatternPlan xCheck = pattern(Term.slot(S), 11, Term.constant(102), 21);
		PatternPlan vProducer = pattern(Term.slot(S), 13, Term.slot(X), 11);
		PatternPlan vCheck = pattern(Term.slot(X), 17, Term.constant(103), 5);
		MultiJoinPlan plan = new MultiJoinPlan(new SlotPlan[] { x, xCheck, vProducer, vCheck }, new MaskedFilter[0]);

		// precondition: the sink leaves the compiler order untouched
		assertThat(plan.derivedFactorizedPlan(0L).order).containsExactly(x, xCheck, vProducer, vCheck);

		MultiJoinPlan.OrderedPlan selected = LmdbNativeFactorizedRows.selectFactorizedOrder(plan, 0L, 0L, 0);

		assertThat(selected.order)
				.as("two chained root swaps (40→21→11) drift outside the 2x band of the original root; the band "
						+ "must hold against the incumbent root, so only the root-preserving one-move improvement "
						+ "may be adopted")
				.containsExactly(x, vProducer, xCheck, vCheck);
	}

	/**
	 * Pruning-floor veto: identical shape to the adopted root swap, but the displaced root (20) is more selective than
	 * the only pattern that would remain in the flat prefix (25), so moving it out of the prefix is refused even though
	 * the estimate band (20 vs 25) would allow the swap.
	 */
	@Test
	public void pruningFloorVetoesSelectivePatternLeavingPrefix() {
		PatternPlan x = pattern(Term.slot(S), 7, Term.constant(23), 20);
		PatternPlan rblock = pattern(Term.slot(S), 17, Term.slot(S), 25);
		PatternPlan y1 = pattern(Term.slot(S), 19, Term.slot(B), 5);
		PatternPlan y2 = pattern(Term.slot(S), 23, Term.slot(C), 8);
		MultiJoinPlan plan = new MultiJoinPlan(new SlotPlan[] { x, rblock, y1, y2 }, new MaskedFilter[0]);

		MultiJoinPlan.OrderedPlan selected = LmdbNativeFactorizedRows.selectFactorizedOrder(plan, 0L, 0L, 0);

		assertThat(selected.order).containsExactly(x, rblock, y1, y2);
	}

	// --- seed-mask connectivity ------------------------------------------------------------------------------

	/**
	 * Correlated entry: with only ?t seeded, rooting rblock would leave binder (?q ?x only) with no bound slot to join
	 * on — a cartesian product — so the gainful swap must be refused. Seeding ?q as well restores connectivity and the
	 * very same swap must then be adopted. This pins that connectivity counts slots bound outside the join group.
	 */
	@Test
	public void seedOnlyConnectivityVetoesCartesianOrder() {
		PatternPlan binder = pattern(Term.slot(Q), 7, Term.slot(X), 100);
		PatternPlan rblock = pattern(Term.slot(T), 17, Term.slot(T), 50);
		PatternPlan check = pattern(Term.slot(T), 13, Term.constant(29), 500);
		MultiJoinPlan plan = new MultiJoinPlan(new SlotPlan[] { binder, rblock, check }, new MaskedFilter[0]);

		MultiJoinPlan.OrderedPlan selected = LmdbNativeFactorizedRows.selectFactorizedOrder(plan, 1L << T, 0L, 0);

		assertThat(selected.order)
				.as("rooting rblock would disconnect binder: cartesian orders are never adopted")
				.containsExactly(binder, rblock, check);
	}

	/**
	 * With ?t, ?q and ?x all seeded the sink stays inert (binder produces nothing exclusive), yet the same root swap is
	 * now safe: binder joins through seed-bound slots alone, so the reorder must count them as bound and adopt the
	 * order — binder becomes a per-prefix-row check branch behind the repeated-slot root.
	 */
	@Test
	public void seedBoundSlotsCountAsConnected() {
		PatternPlan binder = pattern(Term.slot(Q), 7, Term.slot(X), 100);
		PatternPlan rblock = pattern(Term.slot(T), 17, Term.slot(T), 50);
		PatternPlan check = pattern(Term.slot(T), 13, Term.constant(29), 500);
		MultiJoinPlan plan = new MultiJoinPlan(new SlotPlan[] { binder, rblock, check }, new MaskedFilter[0]);

		MultiJoinPlan.OrderedPlan selected = LmdbNativeFactorizedRows.selectFactorizedOrder(plan,
				(1L << T) | (1L << Q) | (1L << X), 0L, 0);

		assertThat(selected.order)
				.as("with every binder slot seeded the root swap is connected (band 100 vs 50 = 2x, inclusive)")
				.containsExactly(rblock, binder, check);
	}

	// --- aggregate side --------------------------------------------------------------------------------------

	/**
	 * GROUP BY ?g with two counted legs and the ?g-producer third: the incumbent selection only reaches single-branch
	 * per-key sub-counting (branch = gp; c1 and c2 enumerate in the prefix). Sliding gp up twice — two moves, each
	 * shifting one counted leg down one position — frees both legs as branches.
	 */
	@Test
	public void aggregateGroupProducerSlidesAcrossTwoMoves() {
		PatternPlan driver = pattern(Term.slot(S), 11, Term.constant(21), 10);
		PatternPlan c1 = pattern(Term.slot(S), 7, Term.slot(A), 200);
		PatternPlan c2 = pattern(Term.slot(S), 13, Term.slot(B), 300);
		PatternPlan gp = pattern(Term.slot(S), 17, Term.slot(G), 100);
		MultiJoinPlan plan = new MultiJoinPlan(new SlotPlan[] { driver, c1, c2, gp }, new MaskedFilter[0]);

		AggregateSpec[] specs = {
				AggregateSpec.slot("a", A, false, AggKind.COUNT),
				AggregateSpec.slot("b", B, false, AggKind.COUNT) };
		FactorizedTail.Selection selection = FactorizedTail.select(plan, 0L, new int[] { G }, specs,
				LmdbNativeAttemptMetrics.direct());

		assertThat(selection.tail).isNotNull();
		assertThat(selection.tail.branchCount())
				.as("both counted legs must become branches once the group producer moves into the prefix")
				.isEqualTo(2);
		assertThat(selection.derived.order).containsExactly(driver, gp, c1, c2);
	}

	/** The aggregate improvement honours the kill switch too. */
	@Test
	public void aggregateReorderHonoursKillSwitch() {
		PatternPlan driver = pattern(Term.slot(S), 11, Term.constant(21), 10);
		PatternPlan c1 = pattern(Term.slot(S), 7, Term.slot(A), 200);
		PatternPlan c2 = pattern(Term.slot(S), 13, Term.slot(B), 300);
		PatternPlan gp = pattern(Term.slot(S), 17, Term.slot(G), 100);
		MultiJoinPlan plan = new MultiJoinPlan(new SlotPlan[] { driver, c1, c2, gp }, new MaskedFilter[0]);

		AggregateSpec[] specs = {
				AggregateSpec.slot("a", A, false, AggKind.COUNT),
				AggregateSpec.slot("b", B, false, AggKind.COUNT) };
		System.setProperty("rdf4j.lmdb.factorizedReorder.enabled", "false");
		try {
			FactorizedTail.Selection selection = FactorizedTail.select(plan, 0L, new int[] { G }, specs,
					LmdbNativeAttemptMetrics.direct());
			assertThat(selection.tail).isNotNull();
			assertThat(selection.tail.branchCount()).isEqualTo(1);
			assertThat(selection.derived.order).containsExactly(driver, c1, c2, gp);
		} finally {
			System.clearProperty("rdf4j.lmdb.factorizedReorder.enabled");
		}
	}
}
